let S;
let time = 0, freq = 0.05, amp = 200; // wave
let critPts;

function setup() {
  createCanvas(windowWidth, windowHeight);
	background(2, 2, 8);
	describe("noise sine waveform in cyan with purple critical pts (on PI/2) on dark background");
	frameRate(60);

  noFill();
  strokeWeight(3);
	amp = height * 0.4;
	S = max(width, height);

	critPts = [];
  loop();
}

function draw() {
  background(2, 2, 8);
  freq = map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, 0.01, 0.15); //
  updateCritPts(freq);
  drawBg();
  drawWave(freq, amp);
  drawCritPts();
  time += 0.05;
}

function updateCritPts(frequency) {
  critPts = [];
  // critical points occur at multiples of PI/2 (within the visible range)
  for (let x = 0; x < width; x++) {
    let phase = time + x * frequency;
    if (abs(sin(phase) - cos(phase)) < freq) { // Approximation for when slope is near zero
      critPts.push(x);
    }
  }
}

function drawBg() {
  push();
  const d = ~~(max(width, height) / 10);
  strokeWeight(1);
  stroke("rgb(0,64,64)");
	let lx = 0;
  for (let x = (d + frameCount) % d; x < width; x += d) {
    line(x, 0, x - height, height);
		lx = x;
  }
  for (let y = d-(width-lx); y < height; y += d) {
    h = height - y;
    line(width, y, width - h, y + h);
  }
  pop();
}

function drawWave(frequency, amplitude) {
  noFill();
  stroke("cyan");
  beginShape();
  for (let x = 0; x < width; x++) {
    const a = noise((x + frameCount) * 0.123, 424234 + frameCount * 0.012);
    const f = noise((x + frameCount) * 0.00923, 424234 + frameCount * 0.012);
    let y =
      height / 2 +
      sin(time + x * frequency * constrain(f / 5 + 0.9, 0.5, 1.5)) *
        amplitude *
        constrain(a + 0.25, 0, 1);
    vertex(x, y);
  }
  endShape();
}

// Highlight critical points
function drawCritPts() {
  fill("purple"); // Red for critical points
  noStroke();
  for (let cp of critPts) {
    ellipse(cp, height / 2, 8, 8);
  }
}

function noisom(v1, v2, fcd = 234) {
	if (v1>v2) [v1, v2] = [v2, v1];
	const n = noise(v1, v2, frameCount/234);
	return v1+n*(v2-v1);
}

